CREATE OR REPLACE FUNCTION public.ce_claim_specific_job_v1(p_job_id uuid, p_worker_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg public.ce_automation_runtime;
  v_job public.ce_evaluation_job;
  v_global integer;
  v_bucket_running integer;
  v_interactive boolean;
begin
  LOCK TABLE public.c3_uat_conversation_scope IN SHARE MODE;
  perform pg_advisory_xact_lock(hashtextextended('ce-job-claim',0));
  select * into v_cfg from public.ce_automation_runtime where singleton=true;
  select * into v_job from public.ce_evaluation_job where id=p_job_id for update;
  if v_job.id is null then return jsonb_build_object('result','not_found'); end if;
  if NOT public.ce_conversation_evaluable_v1(v_job.conversation_id) then return jsonb_build_object('result','conversation_not_evaluable'); end if;
  if v_job.company_id IS DISTINCT FROM public.ce_runtime_conversation_company(v_job.conversation_id) then return jsonb_build_object('result','tenant_mismatch'); end if;
  perform public.ce_reap_expired_jobs_v1();
  select * into v_job from public.ce_evaluation_job where id=p_job_id for update;
  if v_job.status='running' then return jsonb_build_object('result','already_running','job_id',v_job.id); end if;
  v_interactive := v_job.source in ('manual','ce_dwell','resolved','verified_correction');
  if not coalesce(v_cfg.enabled,false) and not v_interactive then return jsonb_build_object('result','disabled'); end if;
  if v_job.status<>'queued' or v_job.available_at>now() then return jsonb_build_object('result','not_claimable','status',v_job.status); end if;
  select count(*) into v_global from public.ce_evaluation_job where status='running' AND NOT public.c3_uat_learning_excluded(conversation_id);
  if v_global>=v_cfg.global_concurrency then return jsonb_build_object('result','global_busy'); end if;
  select count(*) into v_bucket_running from public.ce_evaluation_job j where j.status='running' and NOT public.c3_uat_learning_excluded(j.conversation_id) and coalesce(j.company_id::text,'__preactivation__')=coalesce(v_job.company_id::text,'__preactivation__');
  if v_bucket_running>=v_cfg.per_company_concurrency then return jsonb_build_object('result','company_busy'); end if;
  update public.ce_evaluation_job set status='running',lease_owner=p_worker_id,lease_expires_at=now()+interval '10 minutes',started_at=coalesce(started_at,now()),attempts=attempts+1,error_code=null,updated_at=now() where id=p_job_id;
  return jsonb_build_object('result','claimed','job_id',p_job_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_widget_session_tx(p_channel_id uuid, p_session_token text, p_visitor_fingerprint text, p_visitor_metadata jsonb, p_page_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_channel record;
  v_session_id uuid;
  v_conversation_id uuid;
  v_origin text;
BEGIN
  IF p_channel_id IS NULL OR p_session_token IS NULL OR length(p_session_token)<32 OR length(p_session_token)>256 THEN
    RETURN jsonb_build_object('result','invalid_input');
  END IF;
  v_origin:=lower(regexp_replace(COALESCE(p_page_url,''), '/$', ''));
  IF v_origin='' OR v_origin !~ '^https://[a-z0-9.-]+(:[0-9]+)?$' THEN
    RETURN jsonb_build_object('result','origin_invalid');
  END IF;
  SELECT id,company_id,is_active,channel_type,allowed_origins INTO v_channel
  FROM public.channel_config WHERE id=p_channel_id FOR SHARE;
  IF NOT FOUND OR v_channel.is_active IS DISTINCT FROM true OR v_channel.channel_type IS DISTINCT FROM 'web_widget' THEN
    RETURN jsonb_build_object('result','channel_not_found');
  END IF;
  IF v_channel.company_id IS NULL THEN RETURN jsonb_build_object('result','channel_company_unresolved'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.company c WHERE c.id=v_channel.company_id AND c.is_active=true) THEN
    RETURN jsonb_build_object('result','company_inactive');
  END IF;
  IF v_channel.allowed_origins IS NULL OR cardinality(v_channel.allowed_origins)=0 OR
     EXISTS(SELECT 1 FROM unnest(v_channel.allowed_origins) a WHERE a IS NULL OR btrim(a)='' OR btrim(a)='*') THEN
    RETURN jsonb_build_object('result','allowed_origins_unconfigured');
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM unnest(v_channel.allowed_origins) a
    WHERE lower(regexp_replace(btrim(a), '/$', ''))=v_origin
      AND lower(regexp_replace(btrim(a), '/$', '')) ~ '^https://[a-z0-9.-]+(:[0-9]+)?$'
  ) THEN
    RETURN jsonb_build_object('result','origin_not_allowed');
  END IF;
  INSERT INTO public.visitor_session(session_token,channel_config_id,visitor_fingerprint,visitor_metadata,last_seen_at)
  VALUES(p_session_token,p_channel_id,NULLIF(left(p_visitor_fingerprint,512),''),COALESCE(p_visitor_metadata,'{}'::jsonb)||jsonb_build_object('origin',v_origin),now())
  RETURNING id INTO v_session_id;
  INSERT INTO public.conversations(visitor_session_id,channel_config_id,company_id,status)
  VALUES(v_session_id,p_channel_id,v_channel.company_id,'open') RETURNING id INTO v_conversation_id;
  INSERT INTO public.widget_session_event(visitor_session_id,event_type,event_data,page_url)
  VALUES(v_session_id,'widget_open',jsonb_build_object('conversation_id',v_conversation_id),v_origin);
  RETURN jsonb_build_object('result','success','session_id',v_session_id,'conversation_id',v_conversation_id);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('result','session_token_conflict');
END;
$function$
